module float_multi (
    input clk, 
    input rst, 
    input [31:0] a, 
    input [31:0] b, 
    output reg [31:0] z
);
    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    // Internal signal declarations

    parameter ZERO = 32'h00000000;
    parameter INFINITY = 32'h7F800000;
    parameter NAN = 32'h7FC00000;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'h0;
        end else begin
            case(counter)
                3'd0: begin
                    a_mantissa[22:0] <= a[22:0];
                    a_exponent[9:0] <= a[30:23] - 127;
                    a_sign <= a[31];
                    if (a_exponent[9]) begin
                        a_mantissa[23] <= 1'b1;
                    end else begin
                        a_mantissa[23] <= 1'b0;
                    end
                end

                3'd1: begin
                    b_mantissa[22:0] <= b[22:0];
                    b_exponent[9:0] <= b[30:23] - 127;
                    b_sign <= b[31];
                    if (b_exponent[9]) begin
                        b_mantissa[23] <= 1'b1;
                    end else begin
                        b_mantissa[23] <= 1'b0;
                    end
                end

                3'd2: begin
                    product[49:0] <= {1'b0, a_mantissa} * {1'b0, b_mantissa};
                    z_sign <= a_sign ^ b_sign;
                    z_exponent[9:0] <= a_exponent + b_exponent + 127;
                end

                3'd3: begin
                    guard_bit <= product[24];
                    round_bit <= product[23];
                    sticky <= |product[22:0];

                    if (guard_bit && (round_bit || sticky || product[24])) begin
                        product[49:25] <= product[49:25] + 1'b1;
                    end
                    if (product[49]) begin
                        z_exponent <= z_exponent + 1'b1;
                        product[49:25] <= product[49:25] >> 1;
                    end
                end

                3'd4: begin
                    z_mantissa <= product[48:25];

                    if ((a_exponent == 128 && a_mantissa != 0) || (b_exponent == 128 && b_mantissa != 0)) begin
                        z <= NAN;
                    end else if (z_exponent >= 127) begin
                        z <= INFINITY;
                    end else begin
                        z[31] <= z_sign;
                        z[30:23] <= z_exponent[7:0] + 127;
                        z[22:0] <= z_mantissa[22:0];
                    end
                end
            endcase

            counter <= counter + 1;
        end
    end
endmodule
